  var PIN_PITCH = 10;
  function symbolLayout(pinCount, pinNums) {
    const L = Math.ceil(pinCount / 2);
    const H = Math.max(1, L - 1) * PIN_PITCH + 20;
    const left = pinNums.slice(0, L);
    const right = pinNums.slice(L);
    return { L, H, left, right };
  }

  // src/schplan.ts
  var STUB_LEN = 24;
  var COL_W = 300;
  var BLOCK_GAP = 90;
  var SLOT_V = 46;
  var MAX_COL_H = 900;
  var ORIGIN_X = 200;
  var ORIGIN_Y = 200;
  function pinKind(net) {
    if (!net) return "nc";
    if (GROUND_NETS.has(net)) return "ground";
    if (POWER_NETS.has(net)) return "power";
    return "signal";
  }
  function symbolPins(part) {
    return part.pads.filter((p) => p.type !== "np_thru_hole").map((p) => p.num).sort((a, b) => {
      const na = parseInt(a, 10);
      const nb = parseInt(b, 10);
      if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
      return a < b ? -1 : 1;
    });
  }
  function planSchematic(data) {
    const comps = [];
    const headers = [];
    const wires = [];
    const labels = [];
    const byRef = new Map(data.parts.map((p) => [p.ref, p]));
    let colX = ORIGIN_X;
    for (const block of BLOCKS) {
      const blockRefs = Object.keys(PARTS).filter((r) => PARTS[r].block === block.id && byRef.has(r));
      if (blockRefs.length === 0) continue;
      const startX = colX;
      let curY = ORIGIN_Y;
      let colMaxY = ORIGIN_Y;
      let blockCols = 0;
      for (const ref of blockRefs) {
        const part = byRef.get(ref);
        const pinNums = symbolPins(part);
        const { L, H, left, right } = symbolLayout(pinNums.length, pinNums);
        const slotH = H + SLOT_V;
        if (curY + slotH > ORIGIN_Y + MAX_COL_H && curY > ORIGIN_Y) {
          colX += COL_W;
          blockCols++;
          curY = ORIGIN_Y;
        }
        const cy = curY + slotH / 2;
        const pins = [];
        const padNet = new Map(part.pads.map((p) => [p.num, p.net]));
        const yTop = -H / 2 + 10;
        left.forEach((n, i) => {
          const x = colX - 60;
          const y = cy + yTop + i * 10;
          const net = padNet.get(n) ?? "";
          const kind = pinKind(net);
          pins.push({ num: n, x, y, dir: -1, net, kind, stubEndX: x - STUB_LEN, stubEndY: y });
        });
        right.forEach((n, j) => {
          const x = colX + 60;
          const y = cy - yTop - j * 10;
          const net = padNet.get(n) ?? "";
          const kind = pinKind(net);
          pins.push({ num: n, x, y, dir: 1, net, kind, stubEndX: x + STUB_LEN, stubEndY: y });
        });
        comps.push({ ref, value: part.value, cx: colX, cy, w: 120, h: H, pins });
        curY += slotH;
        if (curY > colMaxY) colMaxY = curY;
      }
      const blockW = (blockCols + 1) * COL_W;
      headers.push({
        title: block.title,
        x: startX - 140,
        y: ORIGIN_Y - 60,
        w: blockW - 40,
        h: colMaxY - ORIGIN_Y + 90
      });
      colX += blockW + BLOCK_GAP;
    }
    for (const c of comps) {
      for (const p of c.pins) {
        if (p.kind === "nc") continue;
        wires.push([p.x, p.y, p.stubEndX, p.stubEndY]);
        labels.push({ x: p.stubEndX, y: p.stubEndY, net: p.net, kind: p.kind });
      }
    }
    return { comps, headers, wires, labels };
  }

  // src/symdraw.ts
  var SYM_PIN_LEN = 10;
  var BOX_HALF_W = 50;
  function pinOrder(a, b) {
    const na = parseInt(a, 10);
    const nb = parseInt(b, 10);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
    return a < b ? -1 : a > b ? 1 : 0;
  }
  function symbolPinList(part, pm) {
    const spec = PARTS[part.ref];
    const netOf = new Map(part.pads.map((p) => [p.num, p.net]));
    const nameOf = (kicadNum) => spec?.pinNames?.[kicadNum] ?? (netOf.get(kicadNum) || "NC");
    const mapped = pm ? { ...part, pads: part.pads.map((p) => ({ ...p, num: pm[p.num] ?? p.num })) } : part;
    const inv = pm ? new Map(Object.entries(pm).map(([k, v]) => [v, k])) : void 0;
    return symbolPins(mapped).map((n) => {
      const orig = inv?.get(n) ?? n;
      return { num: n, name: nameOf(orig) };
    });
  }
